-- SQL script to create and populate the cobros table
CREATE TABLE IF NOT EXISTS public.cobros (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  alumno text NOT NULL,
  curso text NOT NULL,
  fecha_inicio text,
  fecha_fin text,
  observaciones text,
  d3 text,
  d4 text,
  d5 text,
  d10 text,
  d11 text,
  d12 text,
  d13 text,
  d14 text,
  d17 text,
  d18 text,
  d19 text,
  d20 text,
  d21 text,
  d24 text,
  d25 text,
  d26 text,
  d27 text,
  d28 text,
  d31 text,
  platos_vendidos integer DEFAULT 0,
  platos_vendidos_bs numeric DEFAULT 0,
  color text,
  created_at timestamptz DEFAULT timezone('utc', now()),
  updated_at timestamptz DEFAULT timezone('utc', now())
);

-- Enable Row Level Security
ALTER TABLE public.cobros ENABLE ROW LEVEL SECURITY;

-- Create policy to allow all access (since it's an admin dashboard)
DROP POLICY IF EXISTS "Allow all access to cobros" ON public.cobros;
CREATE POLICY "Allow all access to cobros" ON public.cobros FOR ALL USING (true) WITH CHECK (true);

-- Truncate existing data if any
TRUNCATE TABLE public.cobros RESTART IDENTITY;

